import { featureFlagEnabled } from "./featureFlag";
import { getCurrentUser } from "./storage";

const escapeRegex = (str: string): string =>
  str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

const standardReg =
  "\\bphone\\b|\\bscreen\\b|\\binterview\\b|#brighthire|lever\\.co|greenhouse\\.io|workable\\.com|smartrecruiters\\.com|brighthire\\.ai";

const reducedReg =
  "\\bscreen\\b|\\binterview\\b|#brighthire|lever\\.co|greenhouse\\.io|workable\\.com|smartrecruiters\\.com|brighthire\\.ai";

export const getEventImportKeywordsRegExp = async (): Promise<RegExp> => {
  const currentUser = await getCurrentUser();
  const useReducedKeywordList = await featureFlagEnabled(
    "browser-extension:reduced-keyword-list",
  );
  const importReg = useReducedKeywordList ? reducedReg : standardReg;
  const keywords =
    currentUser?.eventImportKeywords?.reduce((acc, kw) => {
      if (kw?.keywordText) {
        return `${acc}|${escapeRegex(kw.keywordText)}`;
      }
      return acc;
    }, "") ?? "";

  return new RegExp(importReg + keywords, "gi");
};
