import { buildCalendarButtonContainer } from "../utils/calendarButton";
import { getEventImportKeywordsRegExp } from "../utils/eventImportKeywords";
import {
  featureFlagEnabled,
  inPersonEnabled,
  showJoinWithBrighthire,
} from "../utils/featureFlag";
import { MutationSummary, type Summary } from "../utils/MutationSummary";
import { onDocumentLoaded } from "../utils/onDocumentLoaded";
import {
  parseGoogleMeetUrl,
  parseGreenhouseScorecardUrl,
  parseLeverInterviewId,
  parsePhoneNumber,
  parseTeamsMeetingUrl,
  parseZoomUrl,
} from "../utils/parse";
import { initSentry } from "../utils/sentry";
import { buildUrl } from "../utils/url";

initSentry();

enum OutlookView {
  PreviewWindow = "PREVIEW_WINDOW",
  ReadingPane = "READING_PANE",
}

const findShouldShowButtonText = (
  element: Node | Element,
  reg: RegExp,
): boolean => {
  /* 
    • Interview/Phone/Screen is in the title/location/body
    • A greenhouse or lever link is in the title/location/body
    • A brighthire link is in the title/location/body
    • #brighthire is in the title/location/body
  */
  const desc = element.textContent;
  if (desc != null && reg.exec(desc) != null) return true;

  return false;
};

const shouldShowButton = (
  reg: RegExp,
  elements: Array<Element | Node>,
): boolean => {
  /* 
    • Interview/Phone/Screen is in the title/location/body
    • A greenhouse or lever link is in the title/location/body
    • A brighthire link is in the title/location/body
    • #brighthire is in the title/location/body
  */
  return elements.some((element) => findShouldShowButtonText(element, reg));
};

// Preview window button

const insertBrightHireButton = async (element: Node): Promise<void> => {
  const elementsNodeList = document.querySelectorAll(".VSXvP");
  const elements: Array<Element | Node> = Array.from(elementsNodeList);
  elements.push(element);

  let showButton = await featureFlagEnabled(
    "browser-extension:always-show-interview-button",
  );
  if (showButton === false) {
    if ((await showJoinWithBrighthire()) === true) {
      const reg = await getEventImportKeywordsRegExp();
      showButton = shouldShowButton(reg, elements);
    }
  }

  if (showButton === false) {
    return;
  }

  const brighthireButton = await buildBrighthireButton(
    elements,
    OutlookView.PreviewWindow,
    element?.textContent || "",
  );
  if (!brighthireButton) {
    return;
  }

  const noteContainer = document.querySelector(".jE_We");
  if (noteContainer) {
    const parentDiv = noteContainer.parentNode;
    if (parentDiv) {
      parentDiv.insertBefore(brighthireButton, noteContainer);
    }
  } else {
    // For situations without any event text
    const bottomBar = document.querySelector(".E1RRZ");
    if (bottomBar) {
      const parentDiv = bottomBar.parentNode;
      if (parentDiv) {
        parentDiv.insertBefore(brighthireButton, bottomBar);
      }
    }
  }
};

const buildBrighthireButton = async (
  contentElements: Array<Element | undefined | Node>,
  outlookView: OutlookView,
  eventTitle: string,
): Promise<HTMLDivElement | undefined> => {
  if (contentElements.length < 1) {
    return;
  }

  let phoneNumber: string | undefined;
  let zoomUrl: string | undefined;
  let googleMeetUrl: string | undefined;
  let leverInterviewId: string | undefined;
  let greenhouseScorecardUrl: string | undefined;
  let teamsMeetingUrl: string | undefined;
  contentElements.forEach((e) => {
    if (!phoneNumber) {
      phoneNumber = parsePhoneNumber(e);
    }
    if (!zoomUrl) {
      zoomUrl = parseZoomUrl(e);
    }
    if (!googleMeetUrl) {
      googleMeetUrl = parseGoogleMeetUrl(e);
    }
    if (!leverInterviewId) {
      leverInterviewId = parseLeverInterviewId(e);
    }
    if (!greenhouseScorecardUrl) {
      greenhouseScorecardUrl = parseGreenhouseScorecardUrl(e);
    }
    if (!teamsMeetingUrl) {
      teamsMeetingUrl = parseTeamsMeetingUrl(e);
    }
  });

  if (
    !phoneNumber &&
    !zoomUrl &&
    !googleMeetUrl &&
    !leverInterviewId &&
    !greenhouseScorecardUrl &&
    !teamsMeetingUrl
  ) {
    return;
  }

  let isInPerson = false;
  const buttonRow = document.createElement("div");
  const brighthireButton = document.createElement("a");

  let url: URL;
  if (zoomUrl) {
    // Zoom
    brighthireButton.innerHTML = "Interview with BrightHire";
    url = await buildUrl("/interview-assistant/integrations/zoom/", {
      joinUrl: zoomUrl,
      entryPoint: "CHROME_EXTENSION",
    });
  } else if (googleMeetUrl) {
    // Google Meet
    brighthireButton.innerHTML = "Interview with BrightHire";
    url = await buildUrl("/interview-assistant/integrations/googleMeet/", {
      googleMeetUrl,
      entryPoint: "CHROME_EXTENSION",
    });
  } else if (teamsMeetingUrl) {
    // Google Meet
    brighthireButton.innerHTML = "Interview with BrightHire";
    url = await buildUrl("/interview-assistant/integrations/teams/", {
      teamsNotetakerMeetingUrl: teamsMeetingUrl,
      entryPoint: "CHROME_EXTENSION",
    });
  } else if (leverInterviewId) {
    // Lever
    brighthireButton.innerHTML = "Call With BrightHire";
    url = await buildUrl("/interview-assistant/integrations/lever/", {
      interviewId: leverInterviewId,
    });
  } else if (greenhouseScorecardUrl) {
    // Greenhouse
    brighthireButton.innerHTML = "Call With BrightHire";
    url = await buildUrl("/interview-assistant/integrations/greenhouse/", {
      scorecardUrl: greenhouseScorecardUrl,
    });
  } else if (phoneNumber) {
    // Phone
    brighthireButton.innerHTML = "Call With BrightHire";
    url = await buildUrl("/interview-assistant/integrations/outlookWebApp", {
      phoneNumber,
      eventTitle,
    });
  } else {
    // Default route
    brighthireButton.innerHTML = "Call With BrightHire";
    url = await buildUrl("/interview-assistant", {});
  }

  brighthireButton.onclick = () => {
    if (isInPerson) {
      url.searchParams.set("isInPersonInterview", "true");
    } else {
      url.searchParams.delete("isInPersonInterview");
    }
    chrome.runtime.sendMessage({
      action: "openIA",
      payload: { url, windowAvailHeight: window.screen.availHeight },
    });
  };

  const container = buildCalendarButtonContainer({
    brighthireButton,
    inPersonAllowed: await inPersonEnabled(),
    onInPersonClicked: (e) => {
      isInPerson = true;
      brighthireButton.onclick?.(e);
    },
    onInPersonCleared: () => {
      isInPerson = false;
    },
    gap: outlookView === OutlookView.ReadingPane ? "16px" : "12px",
    margin: outlookView === OutlookView.ReadingPane ? "14px 18px" : "8px 18px",
  });

  buttonRow.appendChild(container);

  const dividerElement = document.querySelector(".eYxy6");
  if (dividerElement) {
    buttonRow.appendChild(dividerElement.cloneNode());
  }

  return buttonRow;
};

// Expanded window button

const insertBrightHireButtonReadingPane = async (
  element: Node,
): Promise<void> => {
  const elementsNodeList = document.querySelectorAll(".VSXvP");
  const elements: Array<Element | Node> = Array.from(elementsNodeList);

  const readingPaneTitle = element.childNodes.item(1);
  elements.push(readingPaneTitle);

  let showButton = await featureFlagEnabled(
    "browser-extension:always-show-interview-button",
  );
  if (showButton === false) {
    if ((await showJoinWithBrighthire()) === true) {
      const reg = await getEventImportKeywordsRegExp();
      showButton = shouldShowButton(reg, elements);
    }
  }

  if (showButton === false) {
    return;
  }

  const brighthireButton = await buildBrighthireButton(
    elements,
    OutlookView.ReadingPane,
    readingPaneTitle?.textContent || "",
  );
  if (!brighthireButton) {
    return;
  }

  const noteContainer = document.querySelector(".Q_uMf");
  if (noteContainer) {
    const parentDiv = noteContainer.parentNode;
    if (parentDiv) {
      parentDiv.insertBefore(brighthireButton, noteContainer);
    }
  } else {
    // For situations without any event text
    const contentDiv = document.querySelector(".xJK1Z");
    if (contentDiv) {
      contentDiv.appendChild(brighthireButton);
    }
  }
};

const handleEventMutation = (summaries: Summary[]): void => {
  if (summaries.length > 0 && summaries[0].added.length > 0) {
    insertBrightHireButton(summaries[0].added[0]);
  }
};

const handleReadingPaneMutation = (summaries: Summary[]): void => {
  if (summaries.length > 0 && summaries[0].added.length > 0) {
    insertBrightHireButtonReadingPane(summaries[0].added[0]);
  }
};

