import {
  googleMeetUrlRegex,
  greenhouseScorecardRegex,
  leverInterviewLinkRegex,
  phoneNumberRegex,
  teamsMeetingUrlRegex,
  zoomUrlRegex,
} from "./regex";

export const parseGoogleLink = (u: string): string | null => {
  const url = new URL(u);
  if (url.host.includes("google.com") && url.host !== "meet.google.com") {
    return url.searchParams.get("q");
  }
  return url.toString();
};

export const parsePhoneNumber = (
  element?: Node | Element,
): string | undefined => {
  return parsePhoneNumberStr(element?.textContent || "");
};

export const parsePhoneNumberStr = (phoneStr: string): string | undefined => {
  const textContent = phoneStr.replace(/(\r\n|\n|\r)/gm, "");
  const regPhone = /(?:[-+() ]*\d){10,13}/;
  const text = regPhone.exec(textContent)?.[0]?.replace(/[^0-9.]+/g, "");
  return phoneNumberRegex.exec(text ?? "")?.[0];
};

export const parseEmail = (
  emailElements: NodeListOf<Element>,
): string | undefined => {
  let candidateEmail: string | undefined;
  emailElements.forEach((e) => {
    if (e.textContent?.includes("@")) {
      candidateEmail = e.textContent.trim();
    }
  });
  return candidateEmail;
};

export const parseZoomUrl = (element?: Element | Node): string | undefined => {
  return zoomUrlRegex.exec(element?.textContent || "")?.[0];
};

export const parseGoogleMeetUrl = (
  element?: Element | Node,
): string | undefined => {
  const parsedUrl = googleMeetUrlRegex.exec(element?.textContent || "");
  if (parsedUrl) {
    return `https://${parsedUrl[0]}`;
  }
};

export const parseLeverInterviewId = (
  element?: Element | Node,
): string | undefined => {
  const link = leverInterviewLinkRegex.exec(element?.textContent || "");
  if (link !== null) {
    const leverInterviewLink = new URL(link[0]);
    const { pathname } = leverInterviewLink;
    const paths = pathname.split("/");
    const interviewsIdx = paths.indexOf("interviews");
    if (interviewsIdx !== -1 && paths.length >= interviewsIdx + 1) {
      return paths[interviewsIdx + 1];
    }
  }
};

export const parseGreenhouseScorecardUrl = (
  element?: Node | Element | Node,
): string | undefined => {
  return greenhouseScorecardRegex.exec(element?.textContent || "")?.[0];
};

export const parseTeamsMeetingUrl = (
  element?: Element | Node,
): string | undefined => {
  let teamsMeetingUrl = teamsMeetingUrlRegex.exec(
    element?.textContent || "",
  )?.[0];
  if (teamsMeetingUrl) {
    if (teamsMeetingUrl.endsWith('"')) {
      teamsMeetingUrl = teamsMeetingUrl.slice(0, -1);
    }
    return `https://${teamsMeetingUrl}`;
  }
};
